$(function(){$("table").on("change","input[data-type='int'], input[data-type='float']",function(){$("[data-type='int'], [data-type='float']").each(function(){if($(this).val()==="")$(this).val(0)});var total_qty=0;$("table.dynamic.requisition tbody tr").each(function(){var qty=parseFloat($("[data-js='qty']",this).val());total_qty+=qty});$(".total_qty").html(thousandSep(round(total_qty)))})});